package engine_test

import (
	"log/slog"
	"testing"

	"github.com/acityonmars/martian-robots/internal/engine"
)

func newTestWorld(upperRight engine.Position) *engine.World {
	return engine.NewWorld(upperRight, slog.New(slog.DiscardHandler))
}

func Test_CommandFor_Returns_Command_For_Supported_Letters_Only(t *testing.T) {
	t.Run("L, R, F map to their commands", func(t *testing.T) {
		cases := map[rune]engine.Command{
			'L': engine.TurnLeft{},
			'R': engine.TurnRight{},
			'F': engine.MoveForward{},
		}
		for letter, want := range cases {
			got, ok := engine.GenerateCommandFrom(letter)
			if !ok || got != want {
				t.Errorf("CommandFor(%q) = %T, %v; want %T, true", letter, got, ok, want)
			}
		}
	})

	t.Run("unknown and lowercase letters are rejected", func(t *testing.T) {
		for _, letter := range []rune{'X', 'l', ' '} {
			if _, ok := engine.GenerateCommandFrom(letter); ok {
				t.Errorf("CommandFor(%q) ok = true, want false", letter)
			}
		}
	})
}

func Test_Turn_Commands_Rotate_90_Degrees_Without_Moving(t *testing.T) {
	cases := []struct {
		name  string
		cmd   engine.Command
		start engine.Orientation
		want  engine.Orientation
	}{
		{"left from N", engine.TurnLeft{}, engine.North, engine.West},
		{"left from W", engine.TurnLeft{}, engine.West, engine.South},
		{"left from S", engine.TurnLeft{}, engine.South, engine.East},
		{"left from E", engine.TurnLeft{}, engine.East, engine.North},
		{"right from N", engine.TurnRight{}, engine.North, engine.East},
		{"right from E", engine.TurnRight{}, engine.East, engine.South},
		{"right from S", engine.TurnRight{}, engine.South, engine.West},
		{"right from W", engine.TurnRight{}, engine.West, engine.North},
	}
	for _, tc := range cases {
		t.Run(tc.name, func(t *testing.T) {
			start := engine.Position{X: 1, Y: 1}
			robot := &engine.Robot{Pos: start, Ori: tc.start}

			tc.cmd.ApplyTo(robot, newTestWorld(engine.Position{X: 5, Y: 3}))

			if robot.Ori != tc.want {
				t.Errorf("orientation = %v, want %v", robot.Ori, tc.want)
			}
			if robot.Pos != start {
				t.Errorf("position = %v, want unchanged %v", robot.Pos, start)
			}
		})
	}
}

func Test_MoveForward_Moves_One_Cell_In_Facing_Direction(t *testing.T) {
	cases := []struct {
		name string
		ori  engine.Orientation
		want engine.Position
	}{
		{"north is y+1", engine.North, engine.Position{X: 2, Y: 3}},
		{"east is x+1", engine.East, engine.Position{X: 3, Y: 2}},
		{"south is y-1", engine.South, engine.Position{X: 2, Y: 1}},
		{"west is x-1", engine.West, engine.Position{X: 1, Y: 2}},
	}
	for _, tc := range cases {
		t.Run(tc.name, func(t *testing.T) {
			robot := &engine.Robot{Pos: engine.Position{X: 2, Y: 2}, Ori: tc.ori}

			engine.MoveForward{}.ApplyTo(robot, newTestWorld(engine.Position{X: 5, Y: 3}))

			if robot.Pos != tc.want {
				t.Errorf("position = %v, want %v", robot.Pos, tc.want)
			}
			if robot.Ori != tc.ori {
				t.Errorf("orientation = %v, want unchanged %v", robot.Ori, tc.ori)
			}
			if robot.Lost {
				t.Error("robot lost on an on-grid move")
			}
		})
	}
}
